import React, { useState, useEffect } from "react";
import { Plus } from "lucide-react";
import axios from "axios";

import JobStats from "../components/JobStats";
import JobTable from "../components/JobTable";
import JobForm from "../components/JobForm";
import ApplicationsTable from "../components/ApplicationsTable"; // For received applications

function JobAdminPage() {
  const [jobs, setJobs] = useState([]);
  const [applications, setApplications] = useState([]); // Placeholder
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingJob, setEditingJob] = useState(null);
  const [activeTab, setActiveTab] = useState("jobs"); // "jobs" or "applications"

  // Fetch jobs from MongoDB
  useEffect(() => {
    axios.get("http://localhost:5000/api/jobs")
      .then(res => setJobs(res.data))
      .catch(err => console.error(err));
  }, []);

  // Add or update job
  const addOrUpdateJob = (job) => {
    if (editingJob) {
      axios.put(`http://localhost:5000/api/jobs/${editingJob.id}`, job)
        .then(res => {
          setJobs(jobs.map(j => j.id === editingJob.id ? res.data : j));
          setEditingJob(null);
          setIsFormOpen(false);
        })
        .catch(err => console.error(err));
    } else {
      axios.post("http://localhost:5000/api/jobs", job)
        .then(res => {
          setJobs([...jobs, res.data]);
          setIsFormOpen(false);
        })
        .catch(err => console.error(err));
    }
  };

  const handleEdit = (job) => {
    setEditingJob(job);
    setIsFormOpen(true);
  };

  const handleDelete = (id) => {
    if (confirm("Are you sure you want to delete this job posting?")) {
      axios.delete(`http://localhost:5000/api/jobs/${id}`)
        .then(() => setJobs(jobs.filter(job => job.id !== id)))
        .catch(err => console.error(err));
    }
  };

  // Styles
  const styles = {
    page: { minHeight: "100vh", padding: "40px", backgroundColor: "#f5f7fb" },
    container: { maxWidth: "1200px", margin: "0 auto" },
    headerCard: {
      background: "#fff",
      borderRadius: "12px",
      padding: "25px 30px",
      display: "flex",
      alignItems: "center",
      justifyContent: "space-between",
      boxShadow: "0 2px 12px rgba(0,0,0,0.05)",
      marginBottom: "20px",
    },
    addButton: {
      display: "flex",
      alignItems: "center",
      gap: "8px",
      backgroundColor: "#2563eb",
      color: "#fff",
      border: "none",
      borderRadius: "8px",
      padding: "10px 18px",
      fontSize: "15px",
      cursor: "pointer",
    },
    tabs: {
      display: "flex",
      gap: "20px",
      marginBottom: "20px",
      cursor: "pointer",
    },
    tab: (active) => ({
      padding: "10px 20px",
      borderRadius: "8px",
      backgroundColor: active ? "#2563eb" : "#fff",
      color: active ? "#fff" : "#1e293b",
      fontWeight: active ? "600" : "500",
      boxShadow: active ? "0 2px 8px rgba(0,0,0,0.1)" : "none",
    }),
  };

  return (
    <div style={styles.page}>
      <div style={styles.container}>
        {/* Header */}
        <div style={styles.headerCard}>
          <h1 style={{ fontSize: "28px", fontWeight: "700" }}>Job Administration</h1>
          {activeTab === "jobs" && (
            <button style={styles.addButton} onClick={() => setIsFormOpen(true)}>
              <Plus size={20} /> Add New Job
            </button>
          )}
        </div>

        {/* Tabs */}
        <div style={styles.tabs}>
          <div style={styles.tab(activeTab === "jobs")} onClick={() => setActiveTab("jobs")}>
            Jobs
          </div>
          <div style={styles.tab(activeTab === "applications")} onClick={() => setActiveTab("applications")}>
            Received Applications
          </div>
        </div>

        {/* Tab Content */}
        {activeTab === "jobs" ? (
          <>
            <JobStats jobs={jobs} />
            <JobTable jobs={jobs} onEdit={handleEdit} onDelete={handleDelete} />
          </>
        ) : (
          <ApplicationsTable applications={applications} />
        )}

        {/* Job Form Modal */}
        {isFormOpen && (
          <JobForm
            job={editingJob}
            onClose={() => setIsFormOpen(false)}
            onSubmit={addOrUpdateJob}
          />
        )}
      </div>
    </div>
  );
}

export default JobAdminPage;
